import { Group, PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- 1. Parse text content ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textData = textItems.find(item => item.role === 'headline') || textItems[0];
  const labelText = textData?.text || 'Get started';
  const fontSize = textData?.typography?.fontSize || 42;

  // --- 2. Create plane geometry & material ---
  const texAspect = 512 / 320; // from atlas region source rect
  const planeWidth = 2.5;
  const planeHeight = planeWidth / texAspect;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff }); // texture will tint
  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0;
  group.add(mesh);

  // --- 3. Load texture asynchronously ---
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- 4. Create text overlay ---
  const textGroup = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: '#ff2a38',         // accent color
    align: 'center',
  });
  textGroup.position.z = 0.01; // slightly in front of plane
  group.add(textGroup);

  // --- 5. Event handlers (none) ---
  group.userData.handlers = {};

  // --- 6. Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // No GSAP timelines to kill
    // The text group resources are managed by ctx.fontAtlas — no manual disposal required
  };

  return group;
}
